int LuaGetMapInfoFile(Lua_State* L)
{
	if (Lua_GetTopIndex(L) != 1) { Lua_PushString(L, (char*)""); return 1; }
	int w = g_SubWorldSet.SearchWorld((DWORD)Lua_ValueToNumber(L, 1));
	if (w < 0 || w >= MAX_SUBWORLD) { Lua_PushString(L, (char*)""); return 1; }
	Lua_PushString(L, SubWorld[w].m_szMapInfoFile);
	return 1;
}

// KJx2WarInfra.cpp canh LuaClearMapObj:
int LuaClearMapTrap(Lua_State* L)
{
	if (Lua_GetTopIndex(L) != 1 || !Lua_IsNumber(L, 1)) return 0;
	int w = g_SubWorldSet.SearchWorld((DWORD)Lua_ValueToNumber(L, 1));
	if (w < 0 || w >= MAX_SUBWORLD) return 0;
	KSubWorld* pWorld = &SubWorld[w];
	for (int r = 0; r < pWorld->m_nTotalRegion; r++)
		memset(pWorld->m_Region[r].m_dwTrap, 0, sizeof(pWorld->m_Region[r].m_dwTrap));
	return 0;
}
