int LuaGetAllEquipment(Lua_State* L)
{
	int nPlayerIndex = GetPlayerIndex(L);
	if (nPlayerIndex <= 0) return 0;
	lua_newtable(L);
	for (int i = 0; i < itempart_num; i++)
	{
		Lua_PushNumber(L, Player[nPlayerIndex].m_ItemList.GetEquipment(i));
		lua_rawseti(L, -2, i + 1);
	}
	return 1;
}

int LuaTm2Time(Lua_State* L)
{
	int n = Lua_GetTopIndex(L);
	if (n < 1) return 0;
	struct tm t; memset(&t, 0, sizeof(t));
	t.tm_year = (int)Lua_ValueToNumber(L, 1) - 1900;
	t.tm_mon  = (n >= 2) ? (int)Lua_ValueToNumber(L, 2) - 1 : 0;
	t.tm_mday = (n >= 3) ? (int)Lua_ValueToNumber(L, 3) : 1;
	t.tm_hour = (n >= 4) ? (int)Lua_ValueToNumber(L, 4) : 0;
	t.tm_min  = (n >= 5) ? (int)Lua_ValueToNumber(L, 5) : 0;
	t.tm_sec  = (n >= 6) ? (int)Lua_ValueToNumber(L, 6) : 0;
	t.tm_isdst = -1;
	Lua_PushNumber(L, (double)mktime(&t));
	return 1;
}
